function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1) return 'mat needs at least one row.';
  const n = mat[0].length;
  if (!Array.isArray(mat[0]) || n < 1) return 'Each row needs at least one value.';
  if (mat.length * n > 100000) return 'mat can hold at most 10^5 cells.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each value is an integer from -10^5 to 10^5.';
  }
  return null;
}

