function maxIncreasingCells(mat) {
  const m = mat.length;
  const n = mat[0].length;
  const cells = [];
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      cells.push([mat[i][j], i, j]);
    }
  }
  cells.sort((a, b) => a[0] - b[0]);
  const rowBest = new Array(m).fill(0);
  const colBest = new Array(n).fill(0);
  let answer = 0;
  let start = 0;
  while (start < cells.length) {
    let end = start;
    while (end < cells.length && cells[end][0] === cells[start][0]) {
      end++;
    }
    const lengths = [];
    for (let k = start; k < end; k++) {
      const [, row, col] = cells[k];
      lengths.push(Math.max(rowBest[row], colBest[col]) + 1);
    }
    for (let k = start; k < end; k++) {
      const [, row, col] = cells[k];
      const length = lengths[k - start];
      rowBest[row] = Math.max(rowBest[row], length);
      colBest[col] = Math.max(colBest[col], length);
      answer = Math.max(answer, length);
    }
    start = end;
  }
  return answer;
}

