function maxIncreasingCells(mat) {
  const m = mat.length, n = mat[0].length;
  const memo = new Map();
  // Longest walk that starts at (r, c), trying every legal jump.
  const walk = (r, c) => {
    const key = r * n + c;
    if (memo.has(key)) return memo.get(key);
    let best = 1;
    for (let j = 0; j < n; j++) if (mat[r][j] > mat[r][c]) best = Math.max(best, 1 + walk(r, j));
    for (let i = 0; i < m; i++) if (mat[i][c] > mat[r][c]) best = Math.max(best, 1 + walk(i, c));
    memo.set(key, best);
    return best;
  };
  let result = 0;
  for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) result = Math.max(result, walk(r, c));
  return result;
}

