function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n, span;
  if (size === 'small') {
    m = pick(1, 4);
    n = pick(1, 4);
    span = [1, 3, 10, 100000][pick(0, 3)];
  } else {
    [m, n] = [[100, 100], [100, 100], [80, 100], [100, 1], [1, 100], [50, 100]][pick(0, 5)];
    span = [5, 50, 1000, 100000][pick(0, 3)];
  }
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => pick(-span, span)))];
}
